import java.util.zip.GZIPInputStream;

public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        System.out.println("task_input  "+taskInput);
        System.out.println("job_input  "+jobInput);
        final int sesssize = params.getInt("sesssize", 600);

        // set up streaming execution environment
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        // Create FileSource for task events
        FileSource<String> taskFileSource = FileSource
                .forRecordStreamFormat(new TextLineInputFormat(), new Path(taskInput))
                .build();

        // Create FileSource for job events
        FileSource<String> jobFileSource = FileSource
                .forRecordStreamFormat(new TextLineInputFormat(), new Path(jobInput))
                .build();

        // Parse task events
        DataStream<TaskEvent> taskEvents = env
                .fromSource(taskSourceOrTest(taskFileSource), WatermarkStrategy
                        .<String>forBoundedOutOfOrderness(Duration.ofSeconds(0))
                        .withTimestampAssigner((event, timestamp) -> {
                            String[] fields = event.split(",", -1);
                            return Long.parseLong(fields[0]);
                        }), "TaskEvents")
                .map(new MapFunction<String, TaskEvent>() {
                    @Override
                    public TaskEvent map(String line) throws Exception {
                        String[] fields = line.split(",", -1);

                        long timestamp = Long.parseLong(fields[0]);
                        String missingInfo = fields[1];
                        long jobId = Long.parseLong(fields[2]);
                        long taskIndex = Long.parseLong(fields[3]);
                        long machineId = fields[4].isEmpty() ? -1 : Long.parseLong(fields[4]);
                        int eventType = Integer.parseInt(fields[5]);
                        String userName = fields[6];
                        int schedulingClass = Integer.parseInt(fields[7]);
                        int priority = Integer.parseInt(fields[8]);
                        double cpuRequest = Double.parseDouble(fields[9]);
                        double memoryRequest = Double.parseDouble(fields[10]);
                        double diskSpaceRequest = Double.parseDouble(fields[11]);
                        int differentMachineConstraint = Integer.parseInt(fields[12]);

                        return new TaskEvent(timestamp, missingInfo, jobId, taskIndex, machineId,
                                eventType, userName, schedulingClass, priority, cpuRequest,
                                memoryRequest, diskSpaceRequest, differentMachineConstraint);
                    }
                })
                .assignTimestampsAndWatermarks(WatermarkStrategy
                        .<TaskEvent>forBoundedOutOfOrderness(Duration.ofSeconds(0))
                        .withTimestampAssigner((event, timestamp) -> event.timestamp));

        // Parse job events
        DataStream<JobEvent> jobEvents = env
                .fromSource(jobSourceOrTest(jobFileSource), WatermarkStrategy
                        .<String>forBoundedOutOfOrderness(Duration.ofSeconds(0))
                        .withTimestampAssigner((event, timestamp) -> {
                            String[] fields = event.split(",", -1);
                            return Long.parseLong(fields[0]);
                        }), "JobEvents")
                .map(new MapFunction<String, JobEvent>() {
                    @Override
                    public JobEvent map(String line) throws Exception {
                        String[] fields = line.split(",", -1);

                        long timestamp = Long.parseLong(fields[0]);
                        String missingInfo = fields[1];
                        long jobId = Long.parseLong(fields[2]);
                        int eventType = Integer.parseInt(fields[3]);
                        String userName = fields[4];
                        int schedulingClass = Integer.parseInt(fields[5]);
                        String jobName = fields[6];
                        String logicalJobName = fields[7];

                        return new JobEvent(timestamp, missingInfo, jobId, eventType, userName,
                                schedulingClass, jobName, logicalJobName);
                    }
                })
                .assignTimestampsAndWatermarks(WatermarkStrategy
                        .<JobEvent>forBoundedOutOfOrderness(Duration.ofSeconds(0))
                        .withTimestampAssigner((event, timestamp) -> event.timestamp));

        // Filter task events to only SUBMIT events (eventType = 0)
        DataStream<TaskEvent> submitEvents = taskEvents
                .filter(event -> event.eventType == 0);

        // Filter job events to only FINISH events (eventType = 4)
        DataStream<JobEvent> finishEvents = jobEvents
                .filter(event -> event.eventType == 4);

        // Process task and job events together
        DataStream<String> results = submitEvents
                .keyBy(task -> task.jobId)
                .connect(finishEvents.keyBy(job -> job.jobId))
                .process(new SessionProcessor(sesssize * 1_000_000L)); // Convert to microseconds

        // Write output to file
        FileSink<String> fileSink = FileSink
                .forRowFormat(new Path(outputPath), new SimpleStringEncoder<String>("UTF-8"))
                .build();

        results.sinkTo(sinkOrTest(fileSink));

        env.execute("LongestSessionPerJob");
    }

    // Process function to track sessions and output longest session per job
    public static class SessionProcessor extends KeyedCoProcessFunction<Long, TaskEvent, JobEvent, String> {

        private final long sessionGap;
        private transient ValueState<List<Session>> sessionsState;
        private transient ValueState<Boolean> jobFinishedState;

        public SessionProcessor(long sessionGap) {
            this.sessionGap = sessionGap;
        }

        @Override
        public void open(Configuration parameters) throws Exception {
            sessionsState = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("sessions", List.class));
            jobFinishedState = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("jobFinished", Boolean.class));
        }

        @Override
        public void processElement1(TaskEvent taskEvent, Context ctx, Collector<String> out) throws Exception {
            // Check if job has already finished
            Boolean finished = jobFinishedState.value();
            if (finished != null && finished) {
                return; // Ignore events after job finish
            }

            List<Session> sessions = sessionsState.value();
            if (sessions == null) {
                sessions = new ArrayList<>();
            }

            long timestamp = taskEvent.timestamp;

            // Find if this event belongs to an existing session
            boolean addedToSession = false;
            for (Session session : sessions) {
                if (timestamp - session.lastTimestamp <= sessionGap) {
                    session.lastTimestamp = timestamp;
                    session.taskCount++;
                    addedToSession = true;
                    break;
                }
            }

            // If not added to existing session, create new session
            if (!addedToSession) {
                Session newSession = new Session();
                newSession.firstTimestamp = timestamp;
                newSession.lastTimestamp = timestamp;
                newSession.taskCount = 1;
                sessions.add(newSession);
            }

            sessionsState.update(sessions);
        }

        @Override
        public void processElement2(JobEvent jobEvent, Context ctx, Collector<String> out) throws Exception {
            // Job finished event received
            jobFinishedState.update(true);

            // Find the longest session
            List<Session> sessions = sessionsState.value();
            if (sessions != null && !sessions.isEmpty()) {
                int maxCount = 0;
                for (Session session : sessions) {
                    if (session.taskCount > maxCount) {
                        maxCount = session.taskCount;
                    }
                }

                // Output the result
                out.collect("(" + jobEvent.jobId + "," + maxCount + ")");
            }
        }
    }

    // Helper class to track session information
    public static class Session implements java.io.Serializable {
        long firstTimestamp;
        long lastTimestamp;
        int taskCount;
    }
}

