public class LongestSessionPerJob extends AppBase {

    public static void main(String[] args) throws Exception {

        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        System.out.println("task_input  "+taskInput);
        System.out.println("job_input  "+jobInput);
        final int sesssize = params.getInt("sesssize", 600);

        // set up streaming execution environment
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();

        // Create custom source functions for reading gzipped CSV files
        SourceFunction<TaskEvent> taskSource = new GZIPTaskEventSource(taskInput);
        SourceFunction<JobEvent> jobSource = new GZIPJobEventSource(jobInput);

        // Parse task events
        DataStream<TaskEvent> taskEvents = env
                .addSource(taskSourceOrTest(taskSource))
                .assignTimestampsAndWatermarks(WatermarkStrategy
                        .<TaskEvent>forBoundedOutOfOrderness(Duration.ofSeconds(0))
                        .withTimestampAssigner((event, timestamp) -> event.timestamp));

        // Parse job events
        DataStream<JobEvent> jobEvents = env
                .addSource(jobSourceOrTest(jobSource))
                .assignTimestampsAndWatermarks(WatermarkStrategy
                        .<JobEvent>forBoundedOutOfOrderness(Duration.ofSeconds(0))
                        .withTimestampAssigner((event, timestamp) -> event.timestamp));

        // Filter task events to only SUBMIT events (eventType = 0)
        DataStream<TaskEvent> submitEvents = taskEvents
                .filter(event -> event.eventType == 0);

        // Filter job events to only FINISH events (eventType = 4)
        DataStream<JobEvent> finishEvents = jobEvents
                .filter(event -> event.eventType == 4);

        // Process task and job events together
        DataStream<String> results = submitEvents
                .keyBy(task -> task.jobId)
                .connect(finishEvents.keyBy(job -> job.jobId))
                .process(new SessionProcessor(sesssize * 1_000_000L)); // Convert to microseconds

        // Write output to file
        org.apache.flink.streaming.api.functions.sink.SinkFunction<String> sink = StreamingFileSink
                .<String>forRowFormat(new Path(outputPath), new SimpleStringEncoder<String>("UTF-8"))
                .build();
        @SuppressWarnings("unchecked")
        org.apache.flink.streaming.api.functions.sink.SinkFunction<String> finalSink =
